select case when s.city in ('London', 'Berlin') then 'tier_1' else 'other' end as city_group, sum(case when p.method = 'cash' then 1 else 0 end) as cash_count, round((100 * sum(case when p.status = 'SUCCESS' then 1 else 0 end)) / count(*), 1) as pct_success from payments p right join orders o on p.order_id = o.id left join stores s on o.store_id = s.id group by case when s.city in ('London', 'Berlin') then 'tier_1' else 'other' end order by city_group
